INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(518, 'deDE', 'Viel zu tun, viel zu tun! Der Verband hat uns Fristen gesetzt, die wir besser nicht überschreiten sollten!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(518, 'esES', '¡Mucho que hacer, mucho que hacer! El sindicato nos ha dado fechas para terminar y no conviene restarles importancia.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(518, 'esMX', '¡Mucho que hacer, mucho que hacer! El sindicato nos ha dado fechas para terminar y no conviene restarles importancia.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(518, 'frFR', 'Beaucoup à faire, beaucoup à faire ! Le Syndicat nous impose des délais du genre qu’on ne dépasse pas !', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(518, 'ptBR', 'Muito a fazer, muito a fazer! Os caras do sindicato nos deram prazos, e com eles não se brinca!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(518, 'ruRU', 'Еще столько всего надо сделать! Союз установил нам жесткие сроки – и лучше бы их не срывать!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(519, 'deDE', 'Direktor Riddlevox hat mir die Verantwortung für das Schredder-Entwicklungsprogramm des Verbands übertragen. Ich bin erst wenige Monate dabei und sitze schon in der Tinte! Ich könnte Eure Hilfe brauchen, $n!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(519, 'esES', 'El director Riddlevox me encargó ocuparme del programa de desarrollo de la trituradora del sindicato. ¡Llevo pocos meses en este trabajo y ya me he metido en un buen lío! ¡Tu ayuda me vendría muy bien, $n!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(519, 'esMX', 'El director Riddlevox me encargó ocuparme del programa de desarrollo de la trituradora del sindicato. ¡Llevo pocos meses en este trabajo y ya me he metido en un buen lío! ¡Tu ayuda me vendría muy bien, $n!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(519, 'frFR', 'Le directeur Riddlevox m\'a chargé du programme du destructeur du Syndicat. Cela fait à peine quelques mois que j\'y travaille et je suis déjà dans le pétrin ! Vous pourriez m\'aider, $n !', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(519, 'ptBR', 'O diretor Charadox me colocou no comando do programa de desenvolvimento do retalhador do sindicato. Trabalho nisso há poucos meses e já estou em maus lençóis! Pode me ajudar, $n?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(519, 'ruRU', 'Директор Ридлвокс назначил меня главным в Союзе по разработке резака. Всего несколько месяцев на новом месте – и уже неприятности! Не поможешь мне, $n?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2433, 'deDE', 'Hallo, Ihr da! Man nennt mich Gregan. Was kann ich für Euch tun?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2433, 'esES', '¡Hola! Me llamo Gregan. ¿Qué puedo hacer por ti?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2433, 'esMX', '¡Hola! Me llamo Gregan. ¿Qué puedo hacer por ti?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2433, 'frFR', 'Salut, je m\'appelle Gregan. Qu\'est-ce que je peux faire pour vous ?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2433, 'ptBR', 'Oie! Meu nome é Gregan. Posso ajudar você?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2433, 'ruRU', 'Привет! Я Греган. Чем могу помочь?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2638, 'deDE', 'Willkommen im Camp Mojache, oh $C. Wie kann ich Euch heute dienen?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2638, 'esES', 'Te doy la bienvenida al Campamento Mojache, valiente $c. ¿De qué manera puedo ayudarte hoy?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2638, 'esMX', 'Te doy la bienvenida al Campamento Mojache, valiente $c. ¿De qué manera puedo ayudarte hoy?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2638, 'frFR', 'Bienvenue au Camp Mojache, brave $c. Comment puis-je vous aider ?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2638, 'ptBR', '$UBem-vindo:Bem-vinda; à Aldeia Mojache, valente $c. Como posso $Uauxiliá-lo:auxiliá-la;?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2638, 'ruRU', 'Добро пожаловать в лагерь Мохаче, $gдоблестный:доблестная:c; |3-6($c). Чем я могу помочь вам?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3293, 'deDE', 'Hallo, $N. Willkommen in der Zuflucht.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3293, 'esES', 'Hola, $N. Te doy la bienvenida al Refugio de la Zaga.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3293, 'esMX', 'Hola, $N. Te doy la bienvenida al Refugio de la Zaga.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3293, 'frFR', 'Bonjour, $N. Bienvenue au refuge de l\'Ornière.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3293, 'ptBR', 'Olá, $N. Bem-vind$Uo:a; à Ponta do Refúgio.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3293, 'ruRU', 'Здравстуйте, $N. Добро пожаловать в Опорный пункт.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3553, 'deDE', 'Ich kam von Süden nach Crossroads und suchte Hilfe, $C, finde aber nur Feiglinge, die sich von mir abwenden - selbst der mächtige Thork beleidigt mich auf diese Weise. Er ist ein großer Anführer, aber dass er mein Flehen nicht erhört, erzürnt mich doch sehr.$B$BEr behauptet, meine Wut mache mich unbedacht, sie beeinträchtige mein Urteilsvermögen, aber ich werde erst ruhen, wenn ich mich gerächt habe!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3553, 'esES', 'Vine a El Cruce desde el Sur buscando ayuda, $c, pero solo encuentro cobardes que me dan la espalda, hasta el poderoso Thork me insulta de este modo. Es un buen líder, pero al rechazar mi petición me ha enfadado mucho.$B$BAfirma que mi cólera me hace ser precipitado, que nubla mi juicio, ¡pero no descansaré hasta que la venganza sea mía!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3553, 'esMX', 'Vine a El Cruce desde el Sur buscando ayuda, $c, pero solo encuentro cobardes que me dan la espalda, hasta el poderoso Thork me insulta de este modo. Es un buen líder, pero al rechazar mi petición me ha enfadado mucho.$B$BAfirma que mi cólera me hace ser precipitado, que nubla mi juicio, ¡pero no descansaré hasta que la venganza sea mía!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3553, 'frFR', 'Je viens du sud pour chercher de l\'aide à la Croisée, $c, mais je n\'y trouve que des lâches qui me tournent le dos. Même le puissant Thork m\'insulte de cette manière. C\'est un bon chef, mais son rejet de ma requête me cause une grande colère.$B$BIl prétend que ma rage me plonge dans la précipitation, qu\'elle obscurcit mon jugement, mais je ne connaîtrai pas le repos avant d\'avoir exercé ma vengeance !', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3553, 'ptBR', 'Vim do sul para a Encruzilhada procurando ajuda, $c, mas só encontro covardes que me dão as costas... Até mesmo o poderoso Thork me insulta. Ele é um bom líder, mas a negligência dele em relação ao meu apelo me enraivece muito.$B$BEle firma que minha fúria me pressa, que prejudica meu juízo, mas não vou descansar até me vingar!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3553, 'ruRU', '$C, я пришел на Перекресток за помощью, но нашел там только трусов, которые отвернулись от меня – даже могучий Торк! Он хороший правитель, но его отказ оскорбил и разозлил меня.$B$BОн говорит, что ярость помутила мне голову, что я не могу мыслить ясно и оттого слишком тороплюсь – но я не успокоюсь, пока не отомщу!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3753, 'deDE', 'Willkommen an der Front, $C. Politiker mögen ja vielleicht an einem Tag untereinander gemeinsame Sache machen und am nächsten Tag Ränke gegeneinander schmieden, aber so etwas können wir uns hier nicht leisten. Dies ist das Bollwerk, hier kämpfen wir jeden Tag erneut um unser Überleben.$B$BWenn Ihr hergekommen seid, um Euch als $GHeld:Heldin; zu beweisen, dann werdet Ihr hier reichlich Gelegenheit dazu haben... vor allem, sobald wir auf Andorhal vorstoßen - auf Andorhal und auf die bösartige Macht, die dort die Geißel kontrolliert.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3753, 'esES', 'Bienvenido a las fronteras, $c. Aunque los políticos pueden dedicarse a conspirar y tramar entre ellos, aquí no se les proporcionarían tales lujos. Esto es El Baluarte y luchamos día a día por una supervivencia que pueda ser duradera.$B$BSi has venido hasta aquí en busca de una oportunidad para mostrarte como un héroe, no te faltarán las ocasiones de hacerlo... especialmente cuando lancemos nuestras ofensivas hacia Andorhal y contra cualquier fuerza maligna que controle ahí a la Plaga.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3753, 'esMX', '$gBienvenido:Bienvenida; a la primera línea, $c. Aunque los políticos conspiren e intriguen entre ellos, aquí verán que no se les permiten tales lujos. Este es el Baluarte, y aquí luchamos por nuestra continua supervivencia día tras día.$B$BSi has venido en busca de una oportunidad para demostrar que eres $gun héroe:una heroína;, encontrarás muchas oportunidades para hacerlo... especialmente porque dirigimos nuestra ofensiva a Andorhal y cualquiera fuerza maligna que controle a la Plaga allí.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3753, 'frFR', 'Bienvenue sur le front, $c. Il est possible que les politiciens aiment à élaborer des plans secrets entre eux, mais ils ne pourront guère pratiquer ici ce genre de loisirs. Nous sommes sur la Barricade, et nous luttons chaque jour pour survivre.$B$BSi vous venez ici pour prouver votre valeur de héros, vous en aurez l\'occasion, surtout quand nous nous mettrons en route vers Andorhal et les forces maléfiques qui y contrôlent le Fléau.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3753, 'ptBR', '$uBem-vindo:Bem-vinda; às linhas de frente, $c. Por mais que os políticos planejem e conspirem entre si, aqui eles não terão os mesmos privilégios. Este é o Baluarte! Aqui lutamos pela nossa sobrevivência todos os dias.$B$BSe você procura uma chance de se provar $Uum herói:uma heroína;, terá várias oportunidades... especialmente à medida que avancemos rumo a Andorhal e a qualquer força maligna que controle o Flagelo por lá.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3753, 'ruRU', 'Добро пожаловать на фронт, |3-6($c). Здесь нет места интригам и хитростям политиков. Здесь, в Бастионе, нам каждый день приходится бороться за жизнь.$B$BЕсли вы хотите совершить подвиг, то здесь найдете предостаточно возможностей для этого… особенно когда мы пойдем на Андорал и бросим вызов тем силам, что повелевают Плетью.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4782, 'deDE', 'Willkommen, $g mein Bruder:meine Schwester;. Wenn Ihr hier seid um zu lernen, dann bin ich nur zu gern bereit, Euch auszubilden.$B$BEs gehen Gerüchte um von Zwistigkeiten innerhalb des Zirkels des Cenarius, aber Ihr solltet solch leichtfertigem Gerede keinen Glauben schenken. Unser Erzdruide, Fandral Staghelm, führt uns und ganz Teldrassil zum Ruhm!', 'Willkommen, $g mein Bruder:meine Schwester;. Wenn Ihr hier seid um zu lernen, dann bin ich nur zu gern bereit, Euch auszubilden.$B$BEs gehen Gerüchte um von Zwistigkeiten innerhalb des Zirkels des Cenarius, aber Ihr solltet solch leichtfertigem Gerede keinen Glauben schenken. Unser Erzdruide, Fandral Staghelm, führt uns und ganz Teldrassil zum Ruhm!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4782, 'esES', '$GBienvenido:Bienvenida;, $ghermano:hermana;. Si has venido aquí para instruirte, estaré encantado de hacerlo.$B$BHay rumores de disputas con el Círculo Cenarion, pero no deberías dar crédito a los que hablan así. ¡Nuestro archidruida, Fandral Corzocelada, nos guía a nosotros y a todo Teldrassil hacia la gloria!', '$GBienvenido:Bienvenida;, $ghermano:hermana;. Si has venido aquí para instruirte, estaré encantado de hacerlo.$B$BHay rumores de disputas con el Círculo Cenarion, pero no deberías dar crédito a los que hablan así. ¡Nuestro archidruida, Fandral Corzocelada, nos guía a nosotros y a todo Teldrassil hacia la gloria!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4782, 'esMX', '$GBienvenido:Bienvenida;, $ghermano:hermana;. Si has venido aquí para instruirte, estaré encantado de hacerlo.$B$BHay rumores de disputas con el Círculo Cenarion, pero no deberías dar crédito a los que hablan así. ¡Nuestro archidruida, Fandral Corzocelada, nos guía a nosotros y a todo Teldrassil hacia la gloria!', '$GBienvenido:Bienvenida;, $ghermano:hermana;. Si has venido aquí para instruirte, estaré encantado de hacerlo.$B$BHay rumores de disputas con el Círculo Cenarion, pero no deberías dar crédito a los que hablan así. ¡Nuestro archidruida, Fandral Corzocelada, nos guía a nosotros y a todo Teldrassil hacia la gloria!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4782, 'frFR', 'Bienvenue, $gmon frère:ma soeur;. Si vous êtes ici pour vous former, j\'aurai plaisir à y contribuer.$B$BOn dit qu\'il y a des dissensions au sein du Cercle cénarien, mais n\'y prêtez pas attention. Notre archidruide, Fandral Staghelm, nous est un guide précieux et mène Teldrassil à la gloire !', 'Bienvenue, $gmon frère:ma soeur;. Si vous êtes ici pour vous former, j\'aurai plaisir à y contribuer.$B$BOn dit qu\'il y a des dissensions au sein du Cercle cénarien, mais n\'y prêtez pas attention. Notre archidruide, Fandral Staghelm, nous est un guide précieux et mène Teldrassil à la gloire !', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4782, 'ptBR', '$uBem-vindo, meu irmão:Bem-vinda, minha irmã;. Se você veio para treinar, então terei muito prazer em ajudar!$B$BHá boatos de dissensões no Círculo Cenariano, mas você não deve dar ouvidos a esses disparates. Nosso Arquidruida, Fandral Guenelmo, nos lidera, e a toda Teldrassil, rumo à glória!', '$uBem-vindo, meu irmão:Bem-vinda, minha irmã;. Se você veio para treinar, então terei muito prazer em ajudar!$B$BHá boatos de dissensões no Círculo Cenariano, mas você não deve dar ouvidos a esses disparates. Nosso Arquidruida, Fandral Guenelmo, nos lidera, e a toda Teldrassil, rumo à glória!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4782, 'ruRU', 'Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; учиться, я с радостью тебе помогу.$B$BСейчас ходит много слухов о раздорах в Круге Кенария, но на них не стоит обращать внимание. Наш верховный друид Фэндрал Олений Шлем ведет к славе нас и весь Тельдрассил!, Добро пожаловать', '$gбрат мой:сестра моя;. Если ты $gпришел:пришла; учиться, я с радостью тебе помогу.$B$BСейчас ходит много слухов о раздорах в Круге Кенария, но на них не стоит обращать внимание. Наш верховный друид Фэндрал Олений Шлем ведет к славе нас и весь Тельдрассил!', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4935, 'deDE', 'Seid gegrüßt, $N, und willkommen im Camp Narache. Die Kunde Eures Kommens hat sich wie ein Lauffeuer im Stamm verbreitet.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4935, 'esES', 'Saludos, $N, y $gbienvenido:bienvenida; a Campamento Narache. Las noticias de tu llegada se han extendido rápidamente entre la tribu.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4935, 'esMX', 'Saludos, $N, y $gbienvenido:bienvenida; a Campamento Narache. Las noticias de tu llegada se han extendido rápidamente entre la tribu.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4935, 'frFR', 'Salutations, $N, et bienvenue au Camp Narache ! Toute la tribu ne parle que de votre venue parmi nous.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4935, 'ptBR', 'Saudações, $N. Bem-$Uvindo:vinda; à Aldeia Narache. A notícia de sua chegada correu rápido pela tribo.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4935, 'ruRU', 'Здравствуй, $N, и добро пожаловать в Лагерь Нараче. Весть о твоем прибытии быстро разошлась в племени.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4937, 'deDE', 'Hmmm, Ihr seht mir recht handfest aus. Vielleicht könnt Ihr mir bei ein, zwei Dingen zur Hand gehen. Außer ein paar Lehrlingen, die noch grün hinter den Ohren sind und anderes zu tun haben, gibt es hier nicht viel Hilfe.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4937, 'esES', 'Ah, ¡qué aspecto tan robusto! Quizás puedas ayudarme con algunas cosas. Por aquí no es necesaria mucha ayuda, excepto para los aprendices verdes, y esos tienen otras cosas por las que preocuparse.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4937, 'esMX', 'Ah, ¡qué aspecto tan robusto! Quizás puedas ayudarme con algunas cosas. Por aquí no es necesaria mucha ayuda, excepto para los aprendices verdes, y esos tienen otras cosas por las que preocuparse.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4937, 'frFR', 'Ah, c\'est que vous m\'avez l\'air solide ! Vous pourrez peut-être m\'aider pour un détail ou deux. Je ne trouve guère d\'aide ici, sauf auprès d\'apprentis sans expérience, et ils ont d\'autres chats à fouetter.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4937, 'ptBR', 'Mas olha se tu não é mais parrud$Uo:a; que carneiro na engorda! Talvez tu possa me ajudar com uma coisa ou outra. Capaz que essa aprendizada cheirando a leite vai dar conta... Não tem mais ninguém por aqui, e eles têm muito mais o que fazer.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4937, 'ruRU', 'О, кто это у нас тут такой крепкий? Возможно, ты сможешь мне кое-чем помочь. От зеленых новичков не добьешься никакой помощи, у них и своих проблем полон рот.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5529, 'deDE', '', 'Hört Ihr den Ruf der Jagd, $C? Ihr müsst genau hinhören, denn der Ruf kommt aus Eurem Inneren. Er kommt tief aus dem Inneren von uns allen.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5529, 'esES', '', '¿Oyes la llamada de la caza, $c? Debes escuchar atentamente, la llamada viene desde muy adentro de ti. Desde muy adentro de todos nosotros.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5529, 'esMX', '', '¿Oyes la llamada de la caza, $c? Debes escuchar atentamente, la llamada viene desde muy adentro de ti. Desde muy adentro de todos nosotros.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5529, 'frFR', '', 'Entendez-vous l\'appel de la chasse, $c ? Vous devez écouter attentivement, l\'appel vient des profondeurs de votre être. De notre être à tous.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5529, 'ptBR', '', 'Você ouve o chamado da caçada, $c? Você precisa ouvir com atenção, mas o chamado vem lá do fundo. Ele vem lá do fundo em todos nós.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5529, 'ruRU', '', 'Слышишь зов охоты, |3-6($c)? Прислушайся внимательно – этот зов звучит внутри тебя. Внутри всех нас.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7114, 'deDE', 'Vielleicht war das doch nicht so ein guter Standpunkt für ein Geschäft...', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7114, 'esES', 'Después de todo, quizás este lugar no era el indicado para una tienda...', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
