(8321, 'ptBR', 'O conteúdo das páginas deste tomo parece estar em constante fluxo. Você sente que os pensamentos estão sendo sangrados da sua mente e consumidos pelo livro.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8321, 'ruRU', 'Текст на страницах этой книги постоянно изменяется. Вы чувствуете, что она словно бы вытягивает из вашей головы мысли и поглощает их.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8332, 'deDE', 'Thrall hat mir große Güte gezeigt, als er mir Schutz in seinem Reich anbot. Ich will nicht länger hier verweilen, als ich willkommen bin. Es wäre eine große Schmach für mich, wenn ich unseren Anführer in Gefahr bringen sollte.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8332, 'esES', 'Thrall ha sido muy generoso acogiéndome en su dominio. De ningún modo quisiera abusar de su hospitalidad. Causarle problemas a nuestro líder sería una gran deshonra para mí.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8332, 'esMX', 'Thrall ha sido muy generoso acogiéndome en su dominio. De ningún modo quisiera abusar de su hospitalidad. Causarle problemas a nuestro líder sería una gran deshonra para mí.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8332, 'frFR', 'Thrall a fait preuve d’une grande générosité en m’accordant l’asile dans son domaine. Je ne veux pas abuser de son hospitalité. Si j’attirais des ennuis à notre chef, je serais déshonoré.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8332, 'ptBR', 'Thrall mostrou grande gentileza ao me conceder abrigo em seus domínios. De qualquer forma, não quero me demorar demais. Seria uma grande desonra se eu causasse problemas ao nosso líder.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8332, 'ruRU', 'Тралл был очень добр, предоставив мне святилище в своих владениях. Но я не хотел бы злоупотреблять его добротой. Принеси я нашему лидеру хоть какое-то неудобство, это стало бы для меня вечным позором.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8358, 'deDE', '', 'Seid gegrüßt, $C. Bitte entschuldigt mich, da ich noch ein Wörtchen mit Rimblat zu reden habe. Er ist der Meinung, dass selbst diese Länder noch gerettet werden können.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8358, 'esES', '', 'Hola, $c. Por favor, discúlpame. Estoy manteniendo una conversación con Rimblat. Él cree que la tierra todavía tiene salvación.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8358, 'esMX', '', 'Hola, $c. Por favor, discúlpame. Estoy manteniendo una conversación con Rimblat. Él cree que la tierra todavía tiene salvación.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8358, 'frFR', '', 'Bonjour, $c. Excusez-moi, mais je suis en pleine conversation avec Rimblat. Il pense que même cet endroit peut encore être sauvé.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8358, 'ptBR', '', 'Olá, $c. Peço que me dê licença, pois estou conversando com Rimblat. Ele acredita que esta terra ainda não está condenada.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8358, 'ruRU', '', 'Привет, |3-6($c). Извини, пожалуйста, я тут заговорилась с Римбальтом. Он считает, что даже эту землю еще можно спасти.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(13321, 'deDE', '', 'Von diesem Dock aus fährt die Bravado zwischen Sturmwind und Auberdine hin und her.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(13321, 'esES', '', 'Desde este muelle, El Valentía hace el viaje de ida y vuelta entre Ventormenta y Auberdine.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(13321, 'esMX', '', 'Desde este muelle, El Valentía hace el viaje de ida y vuelta entre Ventormenta y Auberdine.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(13321, 'frFR', '', 'Depuis ce quai, la Bravoure fait l\'aller-retour entre Hurlevent et Auberdine.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(18503, 'frFR', '<Shu te regarde avec impatience.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(32970, 'frFR', NULL, 'Bonjour $N !\n\nConsultez notre guide pratique, en fonction de vos besoins !', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(65000, 'frFR', 'La transmogrification vous permet de changer l’apparence de vos objets sans en modifier les caractéristiques.\nLes objets utilisés pour la transmogrification ne sont plus remboursables, échangeables et deviennent liés à vous.\nLa mise à jour d’un menu actualise l’affichage et les prix.\n\nTout ne peut pas être transmogrifié entre eux.\nLes restrictions incluent, sans s’y limiter :\nSeules les armures et les armes peuvent être transmogrifiées\nLes fusils, arcs et arbalètes peuvent être transmogrifiés entre eux\nLes cannes à pêche ne peuvent pas être transmogrifiées\nVous devez être capable d’équiper les deux objets utilisés dans le processus.\n\nLes transmogrifications restent sur vos objets tant que vous les possédez.\nSi vous essayez de placer l’objet dans la banque de guilde ou de l’envoyer à quelqu’un d’autre, la transmogrification sera retirée.\n\nVous pouvez également retirer les transmogrifications gratuitement chez le transmogrificateur.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70001, 'esES', 'Vivo solo para servir a mi dueño.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70001, 'esMX', 'Vivo solo para servir a mi dueño.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70001, 'ruRU', 'Я живу только для того, чтобы служить хозяину!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70001, 'zhCN', '我愿意为你奉献一切。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70001, 'zhTW', '我願意為你奉獻一切。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70002, 'esES', '¿Necesitas algo?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70002, 'esMX', '¿Necesitas algo?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70002, 'ruRU', 'Тебе что-то нужно?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70002, 'zhCN', '你需要什么吗？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70002, 'zhTW', '你需要什麼嗎？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70003, 'esES', 'Mortales... normalmente mato a miserables como tú a la vista.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70003, 'esMX', 'Mortales... normalmente mato a miserables como tú a la vista.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70003, 'ruRU', 'Смертные... обычно я убиваю тварей вроде тебя как только увижу!', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70003, 'zhCN', '凡人，通常情况下，我会立刻杀了你这混蛋！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70003, 'zhTW', '凡人，通常情況下，我會立刻殺了你這混蛋！', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70004, 'esES', '<Ves lo que se supone que es un destructor de obsidiana. Sin embargo, este se ve diferente, dañado y descolorido, y no reacciona a tu presencia. Recuerdas que la Plaga ha estado usando sus propias versiones de esos en algún momento en el pasado. ¿Cómo diablos terminó aquí? Después de un examen más detallado, notas una abertura en la espalda de la criatura.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70004, 'esMX', '<Ves lo que se supone que es un destructor de obsidiana. Sin embargo, este se ve diferente, dañado y descolorido, y no reacciona a tu presencia. Recuerdas que la Plaga ha estado usando sus propias versiones de esos en algún momento en el pasado. ¿Cómo diablos terminó aquí? Después de un examen más detallado, notas una abertura en la espalda de la criatura.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70004, 'ruRU', '<Перед вами, похоже, обсидиановый разрушитель. Этот, впрочем, выглядит иначе, поврежденный и поблекший, он не реагирует на ваше присутствие. Вам помнится Плеть когда-то давно использовала таких. Как, черт возьми, он оказался здесь? При дальнейшем осмотре вы замечаете щель на его спине.>', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70004, 'zhCN', '<你看着这个黑曜石毁灭者。它看起来有点与众不同，它并没有因为你的伤害而消失，在仔细检查过后，你注意到它的背部有一个小口。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70004, 'zhTW', '<你看著這個黑曜石毀滅者。它看起來有點與眾不同，它並沒有因為你的傷害而消失，在仔細檢查過後，你注意到它的背部有一個小口。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70005, 'esES', '<El Destructor de obsidiana te mira fijamente y emite un gruñido bajo.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70005, 'esMX', '<El Destructor de obsidiana te mira fijamente y emite un gruñido bajo.>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70005, 'ruRU', '<Обсидиановый Разрушитель смотрит на вас и издает глубокий рычащий звук.>', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70005, 'zhCN', '<毁灭者盯着你，发出低沉的咆哮。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70005, 'zhTW', '<毀滅者盯著你，發出低沉的咆哮。>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70006, 'esES', '¿Estás sorprendido, mortal? Como nathrezim menor, tengo que recurrir a buscar aliados. Parece que podrías divertirme al menos.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70006, 'esMX', '¿Estás sorprendido, mortal? Como nathrezim menor, tengo que recurrir a buscar aliados. Parece que podrías divertirme al menos.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70006, 'ruRU', 'Ты удивлен, смертный? Как низший натрезим, я вынужден прибегать к поиску союзников. Ты выглядишь так, будто сможешь меня хотя бы развлечь.', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70006, 'zhCN', '你惊讶吗，凡人？作为一名纳斯雷兹姆，我不得不寻求盟友，你看起来至少可以逗我开心。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70006, 'zhTW', '你驚訝嗎，凡人？作為一名納斯雷茲姆，我不得不尋求盟友，你看起來至少可以逗我開心。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70007, 'esES', '¿Qué pasa ahora, mortal?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70007, 'esMX', '¿Qué pasa ahora, mortal?', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70007, 'ruRU', 'Ну что ещё, смертный?', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70007, 'zhCN', '现在怎么样了，凡人？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(70007, 'zhTW', '現在怎麼樣了，凡人？', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
